/* global importScripts, firebase, self, clients */
// sw-config.js is generated by the Vite plugin (dev middleware + build asset)
// from the same VITE_FIREBASE_* values the app uses.
importScripts('/sw-config.js')
importScripts('https://www.gstatic.com/firebasejs/10.7.0/firebase-app-compat.js')
importScripts('https://www.gstatic.com/firebasejs/10.7.0/firebase-messaging-compat.js')

self.__FIREBASE_CONFIG__ = self.__FIREBASE_CONFIG__ || {
  apiKey: '',
  authDomain: '',
  projectId: '',
  storageBucket: '',
  messagingSenderId: '',
  appId: '',
}

const APP_URL = self.location.origin

try {
  if (self.__FIREBASE_CONFIG__.apiKey && self.__FIREBASE_CONFIG__.projectId) {
    firebase.initializeApp(self.__FIREBASE_CONFIG__)
    const messaging = firebase.messaging()

    messaging.onBackgroundMessage((payload) => {
      const data = payload.data || {}
      const notification = payload.notification || {}

      // Messages with a notification payload are auto-displayed by the SDK —
      // skip so we never double-show. Only data-only messages reach here.
      if (notification.title || notification.body) return

      const title = data.title || 'PillSync Medicine Reminder'
      const body = data.body || 'Time to take your medicine'
      self.registration.showNotification(title, {
        body,
        icon: '/favicon.ico',
        badge: '/favicon.ico',
        data: { url: data.url || '/' },
      })
    })
  }
} catch (e) {
  console.warn('[FCM SW] init skipped', e)
}

self.addEventListener('notificationclick', (event) => {
  event.notification.close()
  const data = event.notification.data || {}
  const url = data.url || '/'
  const fullUrl = url.startsWith('http') ? url : APP_URL + url
  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
      const pillSyncWindows = clientList.filter((client) => client.url.startsWith(APP_URL))
      if (pillSyncWindows.length && 'focus' in pillSyncWindows[0]) {
        return pillSyncWindows[0].focus()
      }
      if (self.clients.openWindow) {
        return self.clients.openWindow(fullUrl)
      }
    }),
  )
})
